import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:provider/provider.dart';import 'package:myapp/pages/LayoutPage/layout_page.dart';import 'package:myapp/pages/Profile/Settings/privacy_policy_page.dart';import 'package:myapp/pages/Profile/Settings/terms_conditions_page.dart';import 'package:myapp/providers/theme_provider.dart';import 'package:myapp/providers/navigation_provider.dart';import 'package:myapp/providers/notification_provider.dart';import 'package:myapp/providers/loading_provider.dart';import 'package:myapp/pages/Cards/ideal_bw_page.dart';import 'package:myapp/pages/Cards/protein_intake_page.dart';import 'package:myapp/pages/Cards/daily_calorie_page.dart';import 'package:myapp/pages/Cards/add_measurement_page.dart';import 'package:myapp/pages/Profile/features_page.dart';import 'package:myapp/pages/authentication/login_page.dart';import 'package:myapp/services/storage_service.dart';import 'package:myapp/utils/app_theme.dart';import 'package:myapp/repositories/local_auth_repository.dart';import 'package:myapp/repositories/local_user_repository.dart';import 'package:myapp/repositories/local_measurement_repository.dart';import 'package:myapp/cubits/auth_cubit.dart';import 'package:myapp/cubits/goals_cubit.dart';import 'package:myapp/cubits/settings_cubit.dart';import 'package:myapp/cubits/progress_cubit.dart';void main() async {  WidgetsFlutterBinding.ensureInitialized();  await StorageService.init();  final userRepository = LocalUserRepository();  await userRepository.reloadFromStorage();  await userRepository.addDefaultUserIfEmpty();  final authRepository = LocalAuthRepository(userRepository);  final measurementRepository = LocalMeasurementRepository();  runApp(FitApp(    userRepository: userRepository,    authRepository: authRepository,    measurementRepository: measurementRepository,  ));}class FitApp extends StatelessWidget {  final LocalUserRepository userRepository;  final LocalAuthRepository authRepository;  final LocalMeasurementRepository measurementRepository;  const FitApp({    super.key,    required this.userRepository,    required this.authRepository,    required this.measurementRepository,  });  @override  Widget build(BuildContext context) {    return MultiProvider(      providers: [        BlocProvider(create: (_) => AuthCubit(authRepository, userRepository)),        BlocProvider(create: (_) => GoalsCubit(userRepository, authRepository)),        BlocProvider(            create: (_) => SettingsCubit(authRepository, userRepository)),        BlocProvider(create: (_) => ProgressCubit(measurementRepository)),        ChangeNotifierProvider(create: (_) => ThemeProvider()),        ChangeNotifierProvider(create: (_) => NavigationProvider()),        ChangeNotifierProvider(create: (_) => NotificationProvider()),        ChangeNotifierProvider(create: (_) => LoadingProvider()),      ],      child: const _FitAppBuilder(),    );  }}class _FitAppBuilder extends StatelessWidget {  const _FitAppBuilder();  @override  Widget build(BuildContext context) {    final themeProvider = context.watch<ThemeProvider>();    final authState = context.watch<AuthCubit>().state;    themeProvider.syncWithUser(authState.user?.darkMode);    return MaterialApp(      debugShowCheckedModeBanner: false,      title: "Fitness Tracker",      themeMode: themeProvider.themeMode,      theme: AppTheme.lightTheme,      darkTheme: AppTheme.darkTheme,      home: authState.isLoggedIn ? const LayoutPage() : const LoginPage(),      routes: {        '/terms-conditions': (context) => const TermsConditionsPage(),        '/privacy-policy': (context) => const PrivacyPolicyPage(),        '/ideal-weight': (context) => const IdealBodyWeightPage(),        '/protein-intake': (context) => const ProteinIntakePage(),        '/daily-calories': (context) => const DailyCaloriePage(),        '/add-measurement': (context) => const AddMeasurementPage(),        '/features': (context) => const FeaturesPage(),        '/login': (context) => const LoginPage(),      },    );  }}